import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"50、【鼎】 巽下離上","description":"周易集註 - 50、【鼎】 巽下離上","frontmatter":{"title":"50、【鼎】 巽下離上","description":"周易集註 - 50、【鼎】 巽下離上"},"headers":[],"relativePath":"classics/jizhu/054.md","filePath":"classics/jizhu/054.md"}'),l={name:"classics/jizhu/054.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_50、【鼎】-巽下離上" tabindex="-1">50、【鼎】 巽下離上 <a class="header-anchor" href="#_50、【鼎】-巽下離上" aria-label="Permalink to “50、【鼎】 巽下離上”">​</a></h1><p>鼎者，烹飪之器，其卦巽下離上，下陰為足，二三四陽為腹，五陰為耳，上陽為鉉，鼎之象也。又以巽木入離火而致烹飪，鼎之用也。《序卦》：革物者，莫若鼎，故受之以鼎，所以次革。</p><p>彖辭，明觀孔子《彖辭》“是以元亨”，則吉字當從《本義》，作衍文。</p><p>《彖》曰：鼎，象也，以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢，巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。亨並庚反</p><p>以卦體釋卦名，又以卦德卦綜卦體釋卦辭。象者，六爻有鼎之象也。巽者入也，以木入於火也。亨煮也，飪熟食也。亨飪有調和之義，故《論語》曰“失飪不食”。象者鼎之體，亨飪者鼎之用，所以名鼎。聖人者君也，聖賢者臣也。古人有聖德者，皆可稱聖，如湯誥稱伊尹為元聖是也。亨飪之事，不過祭祀賓客而已。祭祀之大者，無出於上帝，賓客之重者，無過於聖賢。享上帝貴質，故止曰亨。享聖賢貴豐，故曰大亨。所以享帝用特牲，而享聖賢以饔牲牢禮也。巽而耳目聰明者，內而此心巽順，外而耳目聰明也。離為目，五為鼎耳，故曰耳目。皆有離明之德，故曰聰明。柔進而上行者，鼎綜革，二卦同體，文王綜為一卦，故《雜卦》曰“革去故也，鼎取新也”，言革下卦之離，進而為鼎之上卦也。進而上行，居五之中，應乎二之剛也。若以人事論，內巽外聰，有其德，進而上行，有其位，應乎剛有其輔，是以元亨。</p><h3 id="《象》曰-木上有火-鼎-君子以正位凝命。" tabindex="-1">《象》曰：木上有火，鼎，君子以正位凝命。 <a class="header-anchor" href="#《象》曰-木上有火-鼎-君子以正位凝命。" aria-label="Permalink to “《象》曰：木上有火，鼎，君子以正位凝命。”">​</a></h3><p>正對偏倚言，凝對散漫言。正位者，端莊安正之謂，即齋明盛服，非禮不動也。凝者成也、堅也，命者天之命也，凝命者，天命凝成堅固，國家安於磐石。所謂協乎上下，以承天休也。鼎譬之位，命譬之實。鼎之器正，然後可凝其所受之實。君之位正，然後可凝其所受之命。鼎綜革，故革亦言命。孔子因大禹鑄九鼎象物，成王定鼎於郟鄏，卜世三十，卜年七百，所以說到正位凝命上去。周烈王二十三年，九鼎震，此不能正位凝命之兆也，其後秦遂滅周，取九鼎。則鼎所繫匪輕矣，故以鼎為宗廟之寶器。及天寶五年，宰臣李適之常列鼎爼，具膳羞，中夜，鼎躍相鬬不解，鼎耳及足皆折，豈以明皇不能正位凝命，而有幸蜀之禍與。</p><p>初六，鼎顛趾，利出否，得妾以其子，無咎。</p><p>巽錯震，震為足，趾之象也。巽為長女，位卑居下，妾之象也。震為長子，子之象也。鼎為寶器，主器者莫若長子，則子之意，亦由鼎而來也。顛趾者，顛倒其趾也。凡洗鼎而出水，必顛倒其鼎，以鼎足反加於上，故曰顛趾。否者，鼎中之汙穢也。利出否者，順利其出否也，故孔子曰鼎取新也。得者獲也，得妾者，買妾而獲之也。以者因也，因其子而買妾也。言洗鼎之時，趾乃在下之物，不當加於其上。今顛於上，若悖上下之序矣。然顛趾者，非得已也，以其順利於出否也。亦猶一夫一婦，人道之常，既有妻，豈可得妾?今得其妾，若失尊卑之分矣，然得妾者，不得已也，以其欲生子，而不得不買妾也。得妾以其子，又顛趾出否之象也。</p><p>初六居下，尚未烹飪，正洗鼎之時，顛趾以出否，故有得妾以其子之象。佔者得此，凡事蹟雖若悖其上下尊卑之序，於義則無咎也。</p><h3 id="《象》曰-鼎顛趾-未悖也。利出否-以從貴也。" tabindex="-1">《象》曰：鼎顛趾，未悖也。利出否，以從貴也。 <a class="header-anchor" href="#《象》曰-鼎顛趾-未悖也。利出否-以從貴也。" aria-label="Permalink to “《象》曰：鼎顛趾，未悖也。利出否，以從貴也。”">​</a></h3><p>未悖者，未悖於理也。言以顛趾於鼎之上，雖若顛倒其上下之序，然洗鼎當如此，未為悖理也。貴對賤，言鼎中之否，則賤物也。以從貴言，欲將珍羞貴重之物，相從以實於鼎中，不得不出其否賤，以濯潔也。</p><p>九二，鼎有實，我仇有疾，不我能即，吉。</p><p>鼎有實者，既洗鼎矣，乃實物於其中也。陽實陰虛，故言實。仇者，匹也，對也，指初也。疾者，陰柔之疾也。即者就也。言初雖有疾，九二則剛中自守，不能使我與之即就也。此九二之能事，非戒辭也。</p><p>九二以剛居中，能守其剛中之實德，雖比於初，而不輕於所與，有鼎有美實，我仇有疾，不我能即，而凂我實德之象。佔者如此，則剛中之德不虧，其吉可知矣。</p><h3 id="《象》曰-鼎有實-慎所之也。我仇有疾-終無尤也。" tabindex="-1">《象》曰：鼎有實，慎所之也。我仇有疾*，終無尤也。 <a class="header-anchor" href="#《象》曰-鼎有實-慎所之也。我仇有疾-終無尤也。" aria-label="Permalink to “《象》曰：鼎有實，慎所之也。我仇有疾*，終無尤也。”">​</a></h3><p>慎所之者，慎所往也。此一句亦言九二之能事，非戒辭也，言九二有陽剛之實德，自能慎於所往，擇善而交，不失身於陰黨也。終無尤者，言我仇雖有疾，然慎於所往，不我能即，而不失身於彼，有何過尤哉。</p><ul><li>原文誤作“我仇有吉”。</li></ul><p>九三，鼎耳革，其行塞。雉膏不食，方雨虧悔，終吉。</p><p>三變為離為坎，坎為耳，耳之象也。革者變也，坎為耳痛，耳革之象也。三未變，錯震足為行，三變則成坎陷，不能行矣，行塞之象也。其行塞者，不能行也。離為雉，雉之象也。坎為膏，膏之象也。中爻兌，三變則不成兌口，不食之象也。三變則內坎水，外亦坎水，方雨之象也。鼎之所賴以舉行者耳也，三居木之極，上應火之極，木火既極，則鼎中騰沸，並耳亦熾熱革變，而不可舉移矣，故其行塞也。雨者水也，虧者損也，悔者鼎不可舉移，而雉膏之美味，不得其食，不免至於悔也。方雨虧悔者，言耳革不食，惟救之以水耳。方雨則能虧損其騰沸熾熱之勢，而悔者不至於悔矣。終吉者，鼎可移，美味可食也。</p><p>九三以陽剛居鼎腹之中，本有美實之德，但應與木火之極，烹飪太過，故有耳革行塞，雉膏不食之象。然陽剛得正，故又有方雨虧悔之象。佔者如是，始雖若不利，終則吉也。</p><h3 id="《象》曰-鼎耳革-失其義也。" tabindex="-1">《象》曰：鼎耳革，失其義也。 <a class="header-anchor" href="#《象》曰-鼎耳革-失其義也。" aria-label="Permalink to “《象》曰：鼎耳革，失其義也。”">​</a></h3><p>義者宜也，鼎烹飪之木火不可過，不可不及，方得烹飪之宜。今木火太過，則失烹飪之宜矣，所以耳革也。</p><p>九四，鼎折足，覆公餗，其形渥，兇。</p><p>四變，中爻為震，足之象也。中爻兌，為毀折，折之象也。鼎實近鼎耳，實已滿矣，令震動，覆之象也。餗者羹糝也，八珍之膳，鼎之實也。鼎以享帝養賢，非自私也，故曰公餗。渥者霑濡也，言覆其鼎，而鼎之上皆霑濡其羹糝也。以人事論，項羽之入咸陽，安祿山之陷長安，宗廟燒焚，寶器披離，不復見昔日彼都人士之盛，其形渥之象也。不可依晁氏“其刑剭兇”者，敗國殺身也。若不以象論，以二體論，離巽二卦成鼎，下體巽有足而無耳，故曰耳革。上體離有耳而無足，故曰折足。</p><p>九四居大臣之位，任天下之重者。但我本不中不正，而又下應初六之陰柔，則委任亦非其人，不能勝大臣之任矣，卒至傾覆國家，故有此象。佔者得此，敗國殺身，兇可知矣。</p><h3 id="《象》曰-覆公餗-信如何也。" tabindex="-1">《象》曰：覆公餗，信如何也。 <a class="header-anchor" href="#《象》曰-覆公餗-信如何也。" aria-label="Permalink to “《象》曰：覆公餗，信如何也。”">​</a></h3><p>信者信任也，言以餗委託信任於人，今將餗覆之，則所信任之人為何如也。</p><p>六五，鼎黃耳，金鉉，利貞。</p><p>五為鼎耳，黃中色，五居中，黃耳之象也。此爻變幹金，金鉉之象也。以此爻未變而言，則曰黃，以此爻既變而言，則曰金。在鼎之上，受鉉以舉鼎者耳也。在鼎之外，貫耳以舉鼎者鉉也。蓋鉉為鼎之系，繫於其耳，二物不相離，故並言之。</p><p>六五有虛中之德，上比上九，下應九二，皆其剛明，故有黃耳金鉉之象。鼎既黃耳金鉉，則中之為實者，必美味矣。而佔者則利於貞固也，因陰柔，故戒以此。</p><h3 id="《象》曰-鼎黃耳-中以為實也。" tabindex="-1">《象》曰：鼎黃耳，中以為實也。 <a class="header-anchor" href="#《象》曰-鼎黃耳-中以為實也。" aria-label="Permalink to “《象》曰：鼎黃耳，中以為實也。”">​</a></h3><p>黃中色，言中乃其實德也，故云黃耳。</p><p>上九，鼎玉鉉，大吉，無不利。</p><p>上九居鼎之極，鉉在鼎上，鉉之象也。此爻變震，震為玉，玉鉉之象也。玉豈可為鉉，有此象也，亦如金車之意。鼎之為器，承鼎在足，實鼎在腹，行鼎在耳，舉鼎在鉉，鼎至於鉉，厥功成矣。功成可以養人，亦猶井之元吉，大成也，故大吉無不利。</p><p>上九以陽居陰，剛而能柔，故有溫潤玉鉉之象。佔者得此，凡事大吉，而又行，無不利也。佔者有玉鉉之德，斯應是佔矣。</p><h3 id="《象》曰-玉鉉在上-剛柔節也。" tabindex="-1">《象》曰：玉鉉在上，剛柔節也。 <a class="header-anchor" href="#《象》曰-玉鉉在上-剛柔節也。" aria-label="Permalink to “《象》曰：玉鉉在上，剛柔節也。”">​</a></h3><p>剛柔節者，言以陽居陰，剛而能節之以柔，亦如玉之溫潤矣，所以為玉鉉也。</p>',38)])])}const m=e(l,[["render",t]]);export{_ as __pageData,m as default};
